identity={
'@Riff':'one ginger stocky OTTER with bare furry head, rust waistcoat, flat tucked ivory inner collar, green trousers, brown brogues, white gloves, small permanent right-hip leather holster. No physical detective hat.',
'@Pip':'one chocolate slim OTTER, wire-rim glasses, teal cardigan, mustard shirt, russet trousers, navy shoes, white gloves. Preserve glasses in every visible face.',
'@Guard':'one tan HOUND guard, navy tunic/cap, tan trousers, muddy zigzag tread boots. Full standing height1H equal heroes. Both feet naturally forward.',
'@Crow':'ONE black riveted mechanical crow, red eyes unless power-down/green state prescribed, complete attached beak/head/body/wings/legs/claws. Standing sole-to-crest4H, FOUR TIMES each1H hero/guard, uniformly scaled whole model. Never small2H robot.',
'@Museum':'museum architecture/case and small mounted clock only; object scale stays fixed.',
'@Alley':'wet street and green dumpster with exactly two symmetrical attached hinged lids, both open.',
'@Tower':'fixed tower architecture, left window, already hanging rope, closed/open trapdoor state as timed, fixed red cable and far-right controller. Geometry only.',
'@Diamond':'one golden faceted diamond; exact ownership per action beats.',
'@Machine':'one teal/brass two-coil machine fixed REAR-CENTER against clockwork; receiver stays empty. Never relocates or grows.',
'@Truck':'one cream/red delivery truck, cab road-to-roof2H, bumper length5H, rear cargo deck separate from cab.',
'@Clues':'museum single feather and note only; never outdoor free feathers.',
'@Driver':'one original gray/white badger civilian in brown flat cap/beige shirt/charcoal vest/trousers, seated INSIDE truck cab at wheel. Never Pip.',
'@Blaster':'one actual brass/black ray pistol with copper coil, wood grip and trigger; Riff draws from existing holster, shots from barrel only.',
'@Clock':'bronze rim, ivory clockface,12simpletickmarks,twohands, no numbers anywhere, no seconds hand. Fixed world diameter0.35H when wall clock, mechanical hands almost still.',
'@ScaleReference':'exact NUMERIC standing-height bounds,1:1:1:4. Dimensions ONLY, not rectangles or character designs in film. Equal standing sole-to-head/cap/crest height1H for Riff/Pip/guard, Crow4H. Model size does not change when seated,crouched or posed.',
'@TowerLayout':'definitive fixed world layout derived from approved screenshot: machine REAR-CENTER, clockwork rear, permanent rope left-center, complete Crow RIGHT, fixed cable along floor to far-right curtain controller. One spatial plate, not first frame or extra Crow. Heroes inserted separately at1H, Crow4H. Preserve world anchors, allow camera crop only when explicitly directed.',
'@VehicleLayout':'truck compartment and nearby ramp/window geography ONLY; character sheets supply identities, exact ScaleReference supplies actor heights. One scene, not extra truck or duplicate driver.',
'@CrowVoice':'reference AUDIO excerpt of later Crow voice. Match its deep/dark/ominous baritone pitch,timbre,resonance and restrained metallic texture for EVERY Crow line. Generate new prescribed words, do not repeat sample line or copy sample music.'}
for ch,sc in zip(p['chapters'],scenes):
 ch.setdefault('director_history',[]).append({'continuity_revision':'v01','prompt':ch['prompt'],'shots':ch['shots'],'handoff':ch.get('handoff'),'audio':ch.get('audio'),'source_revision':p['revision']})
 # Only named assets active in this scene; scale guide always present. Tower plate starts at tower arrival.
 body=' '.join(sc[k] for k in ('start','map','lock'))+' '+' '.join(str(v) for sh in sc['shots'] for v in sh.values())
 tags=helper.tags(body)|{'@scalereference'}
 if ch['chapter_index']>=6:tags|={'@towerlayout'}
